int handle_far_jump(struct x86_emulate_ctxt *ctxt) {
    uint16_t selector;
    struct desc_struct descriptor;

    if (ctxt->opcode_len == 2)
        selector =ctxt.read_word(ctxt);
    else
        selector =ctxt.read_byte(ctxt);

    if (load_segment_descriptor(ctxt, selector, &descriptor))
        return EMULATION_FAILED;

    ctxt->eip = ctxt.read_ulong(ctxt);
    ctxt->cs_base = descriptor.base;
    ctxt->cs_limit = descriptor.limit;
    ctxt->cs_ar = descriptor.type;

    return EMULATION_CONTINUE;
}

int handle_far_jump(struct x86_emulate_ctxt *ctxt) {
    uint16_t sel;
    struct desc_struct desc;

    sel = ctxt->opcode.bytes[1];
    if (get_desc(sel, &desc)) {
        return X86EMUL_CONTINUE;
    }

    if (load_segment_descriptor(ctxt, &desc)) {
        return X86EMUL_UNHANDLEABLE;
    }

    ctxt->eip = get_instruction_pointer(ctxt);
    return X86EMUL_CONTINUE;
}

int handle_far_jump(struct x86_emulate_ctxt *ctxt) {
    uint16_t selector;
    struct desc_struct desc;
    int status;

    selector = ctxt->opcode.bytes[1];
    status = get_segment_descriptor(ctxt, selector, &desc);
    if (status != X86EMUL_CONTINUE)
        return status;

    ctxt->eip = (ctxt->opcode.bytes[2] | (ctxt->opcode.bytes[3] << 8) |
                 (ctxt->opcode.bytes[4] << 16) | (ctxt->opcode.bytes[5] << 24));
    ctxt->cs = selector;
    ctxt->mode = DESC_CODE;

    return X86EMUL_CONTINUE;
}

int handle_far_jump(struct x86_emulate_ctxt *ctxt) {
    uint16_t selector;
    struct desc_struct descriptor;

    if (ctxt->opcode_len == 2)
        selector =ctxt->modrm & 0xff00;
    else
        selector = ctxt->modrm & 0x00ff;

    if (!get_desc(selector, &descriptor, ctxt))
        return X86EMUL_UNHANDLEABLE;

    ctxt->eip = (ctxt->rex_prefix & 1) ? ctxt->regs[VCPU_REGS_RIP] : ctxt->regs[VCPU_REGS_IP];
    ctxt->regs[VCPU_REGS_RIP] = ctxt->eip;

    return X86EMUL_CONTINUE;
}

int do_far_jump(struct x86_emulate_ctxt *ctxt) {
    uint16_t sel;
    struct desc_struct descriptor;

    if (ctxt->opcode_only)
        return X86EMUL_CONTINUE;

    sel = ctxt->src.val16;
    if (load_segment_descriptor(ctxt, sel, &descriptor))
        return X86EMUL_UNHANDLEABLE;

    ctxt->eip = ctxt->src.val32u;
    ctxt->regs->cs.selector = sel;
    ctxt->regs->cs.base = get_desc_base(&descriptor);
    ctxt->regs->cs.limit = get_desc_limit(&descriptor);
    ctxt->regs->cs.flags = get_desc_flags(&descriptor);

    return X86EMUL_CONTINUE;
}
